    getLiveness: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Process is alive */
            200: {
                headers: {
                    "Cache-Control"?: "no-store";
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "status": "ok",
                     *       "uptime": 3600,
                     *       "ts": "2026-07-23T19:00:00.000Z"
                     *     }
                     */
                    "application/json": {
                        /**
                         * @example ok
                         * @enum {string}
                         */
                        status: "ok";
                        /**
                         * @description Process uptime in seconds
                         * @example 3600
                         */
                        uptime: number;
                        /**
                         * Format: date-time
                         * @example 2026-07-23T19:00:00.000Z
                         */
                        ts: string;
                    };
                };
            };
        };
    };
    getReadiness: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description All dependencies reachable */
            200: {
                headers: {
                    "Cache-Control"?: "no-store";
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "ok": true,
                     *       "checks": {
                     *         "db": "ok",
                     *         "stellar": "ok"
                     *       },
                     *       "ts": "2026-07-23T19:00:00.000Z"
                     *     }
                     */
                    "application/json": components["schemas"]["HealthStatus"];
                };
            };
            /** @description One or more dependencies unreachable */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "ok": false,
                     *       "checks": {
                     *         "db": "error",
                     *         "stellar": "ok"
                     *       },
                     *       "ts": "2026-07-23T19:00:00.000Z"
                     *     }
                     */
                    "application/json": components["schemas"]["HealthStatus"];
                };
            };
        };
    };
